System.register("chunks:///_virtual/manifest2.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"886e7yMsAZCgJOINzGbJjv/","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-minesweeper",slug:"minesweeper",name:{en:"Minesweeper",it:"Campo minato"},description:{en:"Clear the field without touching a mine. Numbers tell you how many are hiding next door.",it:"Ripulisci il campo senza toccare una mina. I numeri ti dicono quante se ne nascondono accanto."},genre:"puzzle",template_id:"mines",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"minesweeper",long_press_ms:350,modes:[{id:"easy",cols:8,rows:10,mines:10,par_s:60,min_s:5},{id:"medium",cols:8,rows:14,mines:20,par_s:150,min_s:12},{id:"hard",cols:10,rows:18,mines:38,par_s:300,min_s:30}]},scoring_rules:{base_points:1e3},supported_platforms:["web","telegram"],supported_locales:["en","it"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#3B82FF",primary:"#FF2D8B",accent:"#FFC83D",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Colori dal brand kit SetteGames (blu #3B82FF come campo, Scopa/grafica/logo-settegames/marchio.json); caratteri Titan One e Baloo 2 (OFL, da Scopa, come il template reaction); suoni sintetizzati dal codice; celle, mine e bandierine disegnate dal codice. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft"},legal_status:{original_concept:!1,trademark_check:"pending",gambling_mechanics:!1,notes:"Rompicapo di pubblico dominio (campo minato, anni '60-'80). 'Minesweeper' è usato solo come nome generico del genere: nessun nome, grafica, suono o codice di Microsoft (né di altri). Grafica e codice originali SetteGames. Verifica del marchio da completare."},experiment_config:{active:[]},seo:{keywords:["minesweeper","play minesweeper online","minesweeper online free","free minesweeper game","minesweeper on phone","mine puzzle game","logic puzzle online","campo minato online"],headline:{en:"Play Minesweeper online",it:"Gioca a Campo minato online"},long_description:{en:"The classic logic puzzle, rebuilt for your phone. Tap to open cells, read the numbers to work out where the mines hide, and flag them with a long press or the flag button. Your first tap is always safe. Three board sizes, a live timer and a weekly leaderboard: clear the field faster to score more. Free, no download, no sign-up.",it:"Il classico rompicapo di logica, rifatto per il telefono. Tocca per aprire le celle, leggi i numeri per capire dove si nascondono le mine e segnale con un tocco lungo o con il pulsante bandierina. Il primo tocco è sempre sicuro. Tre misure di campo, cronometro e classifica settimanale: più sei veloce, più punti fai. Gratis, senza download né registrazione."},how_to_play:{en:["Pick Easy, Medium or Hard and tap any cell: the first tap is always safe and opens an area.","Each number tells how many mines touch that cell, diagonals included.","Long-press a cell, or switch on flag mode, to plant a flag where you are sure a mine is.","Tap a number that already has all its flags around it to open every other neighbour at once.","Open every safe cell to win. Touch a mine and the round is over.","The clock starts with your first tap: the faster you clear the field, the higher your score."],it:["Scegli Facile, Medio o Difficile e tocca una cella qualsiasi: il primo tocco è sempre sicuro e apre un'area.","Ogni numero dice quante mine toccano quella cella, diagonali comprese.","Tieni premuta una cella, o attiva la modalità bandierina, per piantare una bandierina dove sei sicuro che c'è una mina.","Tocca un numero che ha già tutte le sue bandierine attorno per aprire in un colpo le altre celle vicine.","Apri tutte le celle sicure per vincere. Se tocchi una mina la partita finisce.","Il cronometro parte al primo tocco: più in fretta ripulisci il campo, più alto è il punteggio."]},faq:[{q:{en:"Can I lose on the first tap?",it:"Posso perdere al primo tocco?"},a:{en:"No. The mines are placed only after your first tap, and never on that cell or the eight around it, so the game always opens with a safe area.",it:"No. Le mine vengono piazzate solo dopo il primo tocco, mai su quella cella né sulle otto attorno: la partita si apre sempre con un'area sicura."}},{q:{en:"How do I place a flag on a phone?",it:"Come metto una bandierina dal telefono?"},a:{en:"Hold your finger on a covered cell for about a third of a second, or turn on the flag button under the board: while it is on, every tap places or removes a flag.",it:"Tieni il dito su una cella coperta per circa un terzo di secondo, oppure attiva il pulsante bandierina sotto il campo: finché è acceso, ogni tocco mette o toglie una bandierina."}},{q:{en:"What is chording?",it:"Cos'è l'apertura rapida (chording)?"},a:{en:"When a number already has that many flags around it, tap the number to open all its other neighbours in one go. It is the fastest way to clear the board, but a wrong flag will set off a mine.",it:"Quando attorno a un numero ci sono già tante bandierine quante indica, toccalo per aprire in un colpo tutte le altre celle vicine. È il modo più veloce di ripulire il campo, ma una bandierina sbagliata fa scoppiare una mina."}},{q:{en:"Any tips for beginners?",it:"Qualche consiglio per chi inizia?"},a:{en:"Start from the edges of the open area. A 1 touching a single covered cell means that cell is a mine. Look for 1-2-1 and 1-2-2-1 patterns along walls, and only guess when no number can help you.",it:"Parti dai bordi dell'area aperta. Un 1 che tocca una sola cella coperta vuol dire che lì c'è una mina. Cerca le sequenze 1-2-1 e 1-2-2-1 lungo i bordi, e tira a indovinare solo quando nessun numero ti aiuta."}},{q:{en:"How is the score calculated?",it:"Come si calcola il punteggio?"},a:{en:"Only cleared boards score. Your time runs from the first tap to the last safe cell, and a faster time gives more points. Each board size has its own weekly leaderboard, and every score is checked by replaying your moves on the server.",it:"Fanno punti solo i campi ripuliti. Il tempo va dal primo tocco all'ultima cella sicura, e più sei veloce più punti fai. Ogni misura di campo ha la sua classifica settimanale e ogni punteggio viene controllato rigiocando le tue mosse sul server."}},{q:{en:"Is it free? Do I need to download anything?",it:"È gratis? Devo scaricare qualcosa?"},a:{en:"It is free and runs in your browser or inside Telegram, with no download and no account. Optional colour themes are cosmetic only and never change the game.",it:"È gratis e gira nel browser o dentro Telegram, senza download né account. I temi colore facoltativi sono solo estetici e non cambiano mai il gioco."}}]}}),e("BUILD_INFO",{hash:"61d8317f2dfc41cb",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

